import itertools
import numpy
import scipy
import sympy
from sympy import Poly
from sympy.abc import x

# Define the relative_seek function
class Seekable:
    def __init__(self, data):
        self.data = data
        self.position = 0

    def read(self, n):
        if self.position + n > len(self.data):
            raise ValueError('Not enough data to read')
        result = self.data[self.position:self.position + n]
        self.position += n
        return result

    def relative_seek(self, offset):
        if self.position + offset < 0:
            raise ValueError('Offset out of range')
        self.position += offset

# Define the combination_index, combination_with_replacement_index, permutation_index, and product_index functions
def combination_index(combination, elements):
    return list(combination).index(combination)

def combination_with_replacement_index(combination, elements):
    return list(combination).index(combination)

def permutation_index(combination, elements):
    return list(combination).index(combination)

def product_index(combination, elements):
    return list(combination).index(combination)

# Define the polynomial_eval function
def polynomial_eval(polynomial, value):
    return Poly(polynomial, x).subs(x, value)

# Define the nth_combination_with_replacement function
def nth_combination_with_replacement(n, iterable):
    combinations = itertools.combinations_with_replacement(iterable, n)
    return next(itertools.islice(combinations, n, n + 1))

# Define the sum_of_squares function
def sum_of_squares(iterable):
    return sum(i**2 for i in iterable)

# Define the iterate function
def iterate(initial_value, func, stop=None):
    current_value = initial_value
    while not stop or not stop(current_value):
        yield current_value
        current_value = func(current_value)

# Define the partial_product function
def partial_product(iterable, n):
    return itertools.product(*[iterable] * n)

# Define the unique_in_window function
def unique_in_window(iterable, n):
    window = []
    for item in iterable:
        if item not in window:
            window.append(item)
            if len(window) > n:
                window.pop(0)
        yield item

# Define the polynomial_derivative function
def polynomial_derivative(polynomial):
    return Poly(polynomial, x).diff(x)

# Define the batched, convolve, factor, matmul, numeric_range, sieve, and transpose functions
def batched(iterable, n):
    return itertools.zip_longest(*[iter(iterable)] * n)

def convolve(a, b):
    return scipy.signal.convolve(a, b)

def factor(n):
    return sympy.factorint(n)

def matmul(a, b):
    return numpy.matmul(a, b)

def numeric_range(start, stop, step):
    return numpy.arange(start, stop, step)

def sieve(n):
    return sympy.primerange(n)

def transpose(matrix):
    return numpy.transpose(matrix)
